package com.campusconnect.assignment; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface SubmissionRepository extends JpaRepository<Submission,Long>{List<Submission> findByStudentEmailOrderBySubmittedAtDesc(String email); List<Submission> findByAssignmentIdOrderBySubmittedAtDesc(Long id); Optional<Submission> findByAssignmentIdAndStudentEmail(Long id,String email);}
